<?php
namespace App\Http\Controllers\Api;
use App\Enums\UserRole; use App\Http\Controllers\Controller; use App\Http\Requests\LoginRequest; use App\Http\Requests\RegisterRequest; use App\Models\User; use App\Support\ApiPresenter; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller { public function register(RegisterRequest $request): JsonResponse { $data=$request->validated(); $user=DB::transaction(function() use($data){$u=User::create(['name'=>$data['name'],'email'=>$data['email'],'password'=>$data['password'],'role'=>$data['role']]);if($u->role===UserRole::Provider){$u->provider()->create(['timezone'=>$data['timezone'],'is_active'=>true]);}return $u;});$token=$user->createToken($request->input('device_name','api'))->plainTextToken;return response()->json(['data'=>ApiPresenter::user($user),'token'=>$token],201);} public function login(LoginRequest $request): JsonResponse { $user=User::where('email',$request->validated('email'))->first(); if(!$user||!Hash::check($request->validated('password'),$user->password)){return response()->json(['message'=>'Invalid credentials.'],422);} $token=$user->createToken($request->input('device_name','api'))->plainTextToken;return response()->json(['data'=>ApiPresenter::user($user),'token'=>$token]);} public function me(Request $request): JsonResponse{return response()->json(['data'=>ApiPresenter::user($request->user())]);} public function logout(Request $request): JsonResponse{$request->user()->currentAccessToken()?->delete();return response()->json(['message'=>'Logged out.']);} }
